CREATE TABLE public.exam_lessons (id text PRIMARY KEY, level integer NOT NULL CHECK(level BETWEEN 0 AND 5), title text NOT NULL, source text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, reading_items jsonb NOT NULL DEFAULT '[]');
GRANT SELECT ON public.exam_lessons TO authenticated; GRANT ALL ON public.exam_lessons TO service_role;
ALTER TABLE public.exam_lessons ENABLE ROW LEVEL SECURITY;
CREATE POLICY exam_lessons_read ON public.exam_lessons FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
CREATE TABLE public.exam_questions (id text PRIMARY KEY, lesson_id text NOT NULL REFERENCES public.exam_lessons(id), content jsonb NOT NULL, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
GRANT SELECT,INSERT,UPDATE ON public.exam_questions TO authenticated; GRANT ALL ON public.exam_questions TO service_role;
ALTER TABLE public.exam_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY exam_questions_admin ON public.exam_questions TO authenticated USING(public.is_admin(auth.uid())) WITH CHECK(public.is_admin(auth.uid()));
CREATE TABLE public.exam_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(24),'hex'), owner_id uuid NOT NULL, level integer NOT NULL CHECK(level BETWEEN 0 AND 5), lesson_ids text[] NOT NULL, question_count integer NOT NULL CHECK(question_count>0), settings_key text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,settings_key));
GRANT SELECT,UPDATE ON public.exam_links TO authenticated; GRANT ALL ON public.exam_links TO service_role;
ALTER TABLE public.exam_links ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.exam_can_view(_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin(auth.uid()) OR auth.uid()=_owner OR EXISTS(SELECT 1 FROM public.circle_supervisors s JOIN public.circle_teachers t ON s.circle_id=t.circle_id WHERE s.supervisor_id=auth.uid() AND t.teacher_id=_owner) $$;
REVOKE ALL ON FUNCTION public.exam_can_view(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_can_view(uuid) TO authenticated,service_role;
CREATE POLICY exam_links_read ON public.exam_links FOR SELECT TO authenticated USING(public.exam_can_view(owner_id));
CREATE POLICY exam_links_update ON public.exam_links FOR UPDATE TO authenticated USING(owner_id=auth.uid() OR public.is_admin(auth.uid())) WITH CHECK(owner_id=auth.uid() OR public.is_admin(auth.uid()));
CREATE TABLE public.exam_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), link_id uuid NOT NULL REFERENCES public.exam_links(id), secret_hash text NOT NULL, student_name text NOT NULL CHECK(length(student_name) BETWEEN 2 AND 100), snapshot jsonb NOT NULL DEFAULT '[]', reading_items jsonb NOT NULL DEFAULT '[]', responses jsonb NOT NULL DEFAULT '{}', grades jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'started' CHECK(status IN ('started','submitted')), pending integer NOT NULL DEFAULT 0, score numeric NOT NULL DEFAULT 0, total numeric NOT NULL DEFAULT 0, started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz);
GRANT SELECT ON public.exam_attempts TO authenticated; GRANT ALL ON public.exam_attempts TO service_role;
ALTER TABLE public.exam_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY exam_attempts_read ON public.exam_attempts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.exam_links l WHERE l.id=link_id AND public.exam_can_view(l.owner_id)));
CREATE TABLE public.exam_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, attempt_id uuid NOT NULL REFERENCES public.exam_attempts(id), student_name text NOT NULL, level integer NOT NULL, lesson_titles text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), seen boolean NOT NULL DEFAULT false);
GRANT SELECT,UPDATE ON public.exam_notifications TO authenticated; GRANT ALL ON public.exam_notifications TO service_role;
ALTER TABLE public.exam_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY exam_notifications_read ON public.exam_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY exam_notifications_update ON public.exam_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX exam_attempt_link ON public.exam_attempts(link_id,started_at DESC);
CREATE FUNCTION public.exam_catalog() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') FROM (SELECT jsonb_build_object('id',l.id,'level',l.level,'title',l.title,'source',l.source,'active',l.active,'available',CASE WHEN l.level=0 THEN jsonb_array_length(l.reading_items) ELSE (SELECT count(*) FROM public.exam_questions q WHERE q.lesson_id=l.id AND q.active) END) x FROM public.exam_lessons l WHERE public.is_staff(auth.uid())) z $$;
REVOKE ALL ON FUNCTION public.exam_catalog() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_catalog() TO authenticated;
CREATE FUNCTION public.exam_copy_link(_level integer,_lessons text[],_count integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids text[]; available integer; k text; result public.exam_links; BEGIN IF NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'غير مسموح'; END IF; SELECT array_agg(DISTINCT a ORDER BY a) INTO ids FROM unnest(_lessons) a; IF ids IS NULL OR cardinality(ids)=0 OR cardinality(ids)>200 THEN RAISE EXCEPTION 'اختاري درسًا واحدًا على الأقل'; END IF; IF (SELECT count(*) FROM public.exam_lessons WHERE id=ANY(ids) AND level=_level AND active)<>cardinality(ids) THEN RAISE EXCEPTION 'الدروس غير متاحة'; END IF; IF _level=0 THEN SELECT coalesce(sum(jsonb_array_length(reading_items)),0) INTO available FROM public.exam_lessons WHERE id=ANY(ids); ELSE SELECT count(*) INTO available FROM public.exam_questions WHERE lesson_id=ANY(ids) AND active; END IF; IF _count<1 OR _count>available THEN RAISE EXCEPTION 'العدد المطلوب يتجاوز المتاح: %',available; END IF; k:=_level||':'||array_to_string(ids,',')||':'||_count; INSERT INTO public.exam_links(owner_id,level,lesson_ids,question_count,settings_key) VALUES(auth.uid(),_level,ids,_count,k) ON CONFLICT(owner_id,settings_key) DO UPDATE SET settings_key=excluded.settings_key RETURNING * INTO result; RETURN to_jsonb(result); END $$;
REVOKE ALL ON FUNCTION public.exam_copy_link(integer,text[],integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_copy_link(integer,text[],integer) TO authenticated;
CREATE FUNCTION public.exam_public_link(_token text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('level',l.level,'count',l.question_count,'lessons',(SELECT jsonb_agg(jsonb_build_object('id',s.id,'title',s.title) ORDER BY s.position) FROM public.exam_lessons s WHERE s.id=ANY(l.lesson_ids))) FROM public.exam_links l WHERE l.token=_token AND l.active AND length(_token)=48 $$;
REVOKE ALL ON FUNCTION public.exam_public_link(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_public_link(text) TO anon,authenticated;
CREATE FUNCTION public.exam_public_attempt(_id uuid,_secret text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.exam_attempts; safe jsonb; BEGIN SELECT * INTO a FROM public.exam_attempts WHERE id=_id AND secret_hash=encode(sha256(convert_to(_secret,'UTF8')),'hex'); IF a.id IS NULL OR length(_secret)<>48 THEN RAISE EXCEPTION 'المحاولة غير متاحة'; END IF; SELECT coalesce(jsonb_agg(q-'answer'-'explanation' ORDER BY ord),'[]') INTO safe FROM jsonb_array_elements(a.snapshot) WITH ORDINALITY s(q,ord); RETURN (to_jsonb(a)-'secret_hash'-'snapshot'-'grades')||jsonb_build_object('snapshot',safe); END $$;
REVOKE ALL ON FUNCTION public.exam_public_attempt(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_public_attempt(uuid,text) TO anon,authenticated;
CREATE FUNCTION public.exam_start(_token text,_name text,_secret text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.exam_links; aid uuid; qs jsonb; rs jsonb; BEGIN SELECT * INTO l FROM public.exam_links WHERE token=_token AND active FOR UPDATE; IF l.id IS NULL OR length(_secret)<>48 OR length(trim(_name)) NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'تحققي من الرابط والاسم'; END IF; IF (SELECT count(*) FROM public.exam_attempts WHERE link_id=l.id AND started_at>now()-interval '1 hour')>=200 THEN RAISE EXCEPTION 'محاولات كثيرة؛ حاولي لاحقًا'; END IF; IF l.level=0 THEN SELECT coalesce(jsonb_agg(item),'[]') INTO rs FROM (SELECT i||jsonb_build_object('lessonTitle',s.title) item FROM public.exam_lessons s CROSS JOIN LATERAL jsonb_array_elements(s.reading_items) i WHERE s.id=ANY(l.lesson_ids) ORDER BY s.position LIMIT l.question_count) z; qs:='[]'; IF jsonb_array_length(rs)<l.question_count THEN RAISE EXCEPTION 'لا توجد عناصر قراءة كافية'; END IF; ELSE SELECT coalesce(jsonb_agg(content ORDER BY random()),'[]') INTO qs FROM (SELECT q.content||jsonb_build_object('id',q.id,'lessonId',q.lesson_id,'lessonTitle',s.title,'options',CASE WHEN q.content->>'kind'='order' THEN q.content->'options' WHEN jsonb_typeof(q.content->'options')='array' THEN (SELECT jsonb_agg(v ORDER BY random()) FROM jsonb_array_elements(q.content->'options') v) ELSE '[]'::jsonb END) content FROM (SELECT q.*, row_number() OVER(PARTITION BY lesson_id ORDER BY random()) rn FROM public.exam_questions q WHERE q.lesson_id=ANY(l.lesson_ids) AND q.active) q JOIN public.exam_lessons s ON s.id=q.lesson_id ORDER BY rn,random() LIMIT l.question_count) z; rs:='[]'; IF jsonb_array_length(qs)<l.question_count THEN RAISE EXCEPTION 'لا توجد أسئلة كافية'; END IF; END IF; INSERT INTO public.exam_attempts(link_id,secret_hash,student_name,snapshot,reading_items,total) VALUES(l.id,encode(sha256(convert_to(_secret,'UTF8')),'hex'),trim(_name),qs,rs,CASE WHEN l.level=0 THEN jsonb_array_length(rs) ELSE (SELECT coalesce(sum((q->>'points')::numeric),0) FROM jsonb_array_elements(qs) q) END) RETURNING id INTO aid; RETURN public.exam_public_attempt(aid,_secret); END $$;
REVOKE ALL ON FUNCTION public.exam_start(text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_start(text,text,text) TO anon,authenticated;
CREATE FUNCTION public.exam_save(_id uuid,_secret text,_responses jsonb,_submit boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.exam_attempts; q jsonb; v jsonb; marks jsonb:='{}'; sc numeric:=0; pend integer:=0; owner uuid; lev integer; titles text[]; BEGIN SELECT * INTO a FROM public.exam_attempts WHERE id=_id AND secret_hash=encode(sha256(convert_to(_secret,'UTF8')),'hex') FOR UPDATE; IF a.id IS NULL OR length(_secret)<>48 THEN RAISE EXCEPTION 'المحاولة غير متاحة'; END IF; IF a.status='submitted' THEN RETURN public.exam_public_attempt(_id,_secret); END IF; IF jsonb_typeof(_responses)<>'object' OR octet_length(_responses::text)>150000 THEN RAISE EXCEPTION 'الإجابات غير صالحة'; END IF; IF EXISTS(SELECT 1 FROM jsonb_object_keys(_responses) k WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.snapshot||a.reading_items) q WHERE q->>'id'=k)) THEN RAISE EXCEPTION 'سؤال غير معروف'; END IF; IF _submit THEN FOR q IN SELECT value FROM jsonb_array_elements(a.snapshot) LOOP v:=_responses->(q->>'id'); IF q->>'kind' IN ('written','fill','matching','order','classify','correction','table') THEN pend:=pend+1; ELSIF (q->>'kind'='multi' AND jsonb_typeof(v)='array' AND (SELECT jsonb_agg(x ORDER BY x) FROM jsonb_array_elements(v) x)=(SELECT jsonb_agg(x ORDER BY x) FROM jsonb_array_elements(q->'answer') x)) OR (q->>'kind'<>'multi' AND v=q->'answer') THEN marks:=marks||jsonb_build_object(q->>'id',(q->>'points')::numeric); sc:=sc+(q->>'points')::numeric; ELSE marks:=marks||jsonb_build_object(q->>'id',0); END IF; END LOOP; IF jsonb_array_length(a.reading_items)>0 THEN pend:=jsonb_array_length(a.reading_items); END IF; END IF; UPDATE public.exam_attempts SET responses=_responses,grades=CASE WHEN _submit THEN marks ELSE grades END,score=CASE WHEN _submit THEN sc ELSE score END,pending=CASE WHEN _submit THEN pend ELSE pending END,status=CASE WHEN _submit THEN 'submitted' ELSE 'started' END,submitted_at=CASE WHEN _submit THEN now() ELSE NULL END WHERE id=_id; IF _submit THEN SELECT l.owner_id,l.level INTO owner,lev FROM public.exam_links l WHERE l.id=a.link_id; SELECT array_agg(title ORDER BY position) INTO titles FROM public.exam_lessons WHERE id=ANY((SELECT lesson_ids FROM public.exam_links WHERE id=a.link_id)); INSERT INTO public.exam_notifications(user_id,attempt_id,student_name,level,lesson_titles) VALUES(owner,_id,a.student_name,lev,titles); END IF; RETURN public.exam_public_attempt(_id,_secret); END $$;
REVOKE ALL ON FUNCTION public.exam_save(uuid,text,jsonb,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_save(uuid,text,jsonb,boolean) TO anon,authenticated;
CREATE FUNCTION public.exam_grade(_id uuid,_qid text,_score numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.exam_attempts; maxscore numeric; BEGIN SELECT * INTO a FROM public.exam_attempts WHERE id=_id FOR UPDATE; IF a.id IS NULL OR a.status<>'submitted' OR NOT EXISTS(SELECT 1 FROM public.exam_links l WHERE l.id=a.link_id AND public.exam_can_view(l.owner_id)) THEN RAISE EXCEPTION 'غير مسموح'; END IF; SELECT (q->>'points')::numeric INTO maxscore FROM jsonb_array_elements(a.snapshot) q WHERE q->>'id'=_qid; IF maxscore IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(a.reading_items) q WHERE q->>'id'=_qid) THEN maxscore:=1; END IF; IF maxscore IS NULL OR _score<0 OR _score>maxscore THEN RAISE EXCEPTION 'الدرجة خارج النطاق'; END IF; a.grades:=a.grades||jsonb_build_object(_qid,_score); UPDATE public.exam_attempts SET grades=a.grades,score=(SELECT coalesce(sum(v::numeric),0) FROM jsonb_each_text(a.grades) x(k,v)),pending=(SELECT count(*) FROM jsonb_array_elements(a.snapshot||a.reading_items) q WHERE NOT a.grades ? (q->>'id')) WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.exam_grade(uuid,text,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.exam_grade(uuid,text,numeric) TO authenticated;
CREATE FUNCTION public.exam_freeze_answers() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='submitted' AND (NEW.responses IS DISTINCT FROM OLD.responses OR NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.reading_items IS DISTINCT FROM OLD.reading_items OR NEW.status IS DISTINCT FROM OLD.status) THEN RAISE EXCEPTION 'لا تعديل للإجابات بعد التسليم'; END IF; RETURN NEW; END $$;
CREATE TRIGGER exam_freeze BEFORE UPDATE ON public.exam_attempts FOR EACH ROW EXECUTE FUNCTION public.exam_freeze_answers();
ALTER PUBLICATION supabase_realtime ADD TABLE public.exam_notifications;